(79, 42, '_wp_attachment_metadata', 'a:6:{s:5:\"width\";i:2560;s:6:\"height\";i:1440;s:4:\"file\";s:28:\"2026/11/SkyBackGround-1.jpeg\";s:8:\"filesize\";i:266607;s:5:\"sizes\";a:6:{s:9:\"thumbnail\";a:5:{s:5:\"width\";i:150;s:6:\"height\";i:150;s:4:\"file\";s:28:\"SkyBackGround-1-150x150.jpeg\";s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:5650;}s:6:\"medium\";a:5:{s:5:\"width\";i:300;s:6:\"height\";i:169;s:4:\"file\";s:28:\"SkyBackGround-1-300x169.jpeg\";s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:11429;}s:12:\"medium_large\";a:5:{s:5:\"width\";i:768;s:6:\"height\";i:432;s:4:\"file\";s:28:\"SkyBackGround-1-768x432.jpeg\";s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:53554;}s:5:\"large\";a:5:{s:5:\"width\";i:1024;s:6:\"height\";i:576;s:4:\"file\";s:29:\"SkyBackGround-1-1024x576.jpeg\";s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:86217;}s:9:\"1536x1536\";a:5:{s:5:\"width\";i:1536;s:6:\"height\";i:864;s:4:\"file\";s:29:\"SkyBackGround-1-1536x864.jpeg\";s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:164762;}s:9:\"2048x2048\";a:5:{s:5:\"width\";i:2048;s:6:\"height\";i:1152;s:4:\"file\";s:30:\"SkyBackGround-1-2048x1152.jpeg\";s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:258293;}}s:10:\"image_meta\";a:13:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:0:\"\";s:6:\"camera\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:17:\"created_timestamp\";s:1:\"0\";s:9:\"copyright\";s:0:\"\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:0:\"\";s:11:\"orientation\";s:1:\"0\";s:8:\"keywords\";a:0:{}s:3:\"alt\";s:0:\"\";}}'),
